<?php
/** @var App\Core\View $this */
/** @var array<string, mixed> $t issued transcript (snapshot + items) */
/** @var string $qr SVG generated by App\Helpers\QrCode (no user input inside) */
/** @var string $verifyUrl */
/** @var bool $canRevoke */
$h = $t['snapshot']['header'];
$kk = locale() === 'kk';
$college = $kk ? ($h['college_kk'] ?? '') : ($h['college_ru'] ?? '');
?>
<style>.doc-grid { display: grid; grid-template-columns: 1fr 34mm; gap: 6mm; align-items: start; } .qr svg { width: 34mm; height: 34mm; } .meta td { border: 0; padding: 0.6mm 1mm; } .revoked { border: 2px solid #b91c1c; color: #b91c1c; padding: 3mm; text-align: center; font-weight: 700; margin-bottom: 4mm; } .muted-sm { font-size: 8pt; color: #64748b; word-break: break-all; }</style>
<?php if ($t['status'] === 'revoked'): ?>
    <div class="revoked"><?= e(__('transcripts.revoked_banner', ['date' => format_date((string) $t['revoked_at'])])) ?><?= $t['revoke_reason'] ? ': ' . e($t['revoke_reason']) : '' ?></div>
<?php endif; ?>
<header class="doc-header">
    <?php if ($college !== ''): ?><div class="doc-org"><?= e($college) ?></div><?php endif; ?>
    <h1><?= e(__('transcripts.document')) ?> № <?= e($t['number']) ?></h1>
    <div class="doc-meta"><?= e(__('transcripts.issued_at')) ?>: <?= e(format_date($t['issued_at'])) ?></div>
</header>
<div class="doc-grid">
    <table class="meta">
        <tr><td><?= e(__('users.name')) ?>:</td><td><strong><?= e($h['full_name']) ?></strong></td></tr>
        <tr><td><?= e(__('fields.student_number')) ?>:</td><td><?= e($h['student_number']) ?></td></tr>
        <?php if (!empty($h['birth_date'])): ?><tr><td><?= e(__('fields.birth_date')) ?>:</td><td><?= e(format_date($h['birth_date'])) ?></td></tr><?php endif; ?>
        <tr><td><?= e(__('fields.specialty_id')) ?>:</td><td><?= e($kk ? ($h['specialty_kk'] ?? '—') : ($h['specialty'] ?? '—')) ?></td></tr>
        <tr><td><?= e(__('fields.qualification_id')) ?>:</td><td><?= e($kk ? ($h['qualification_kk'] ?? '—') : ($h['qualification'] ?? '—')) ?></td></tr>
        <tr><td><?= e(__('fields.group_id')) ?>:</td><td><?= e($h['group'] ?? '—') ?><?= !empty($h['course']) ? ', ' . e(__('groups.course_n', ['n' => $h['course']])) : '' ?></td></tr>
        <?php if (!empty($h['enrollment_date'])): ?><tr><td><?= e(__('fields.enrollment_date')) ?>:</td><td><?= e(format_date($h['enrollment_date'])) ?></td></tr><?php endif; ?>
    </table>
    <div class="qr"><?= $qr ?><div class="muted-sm"><?= e(__('transcripts.qr_hint')) ?></div></div>
</div>

<?= $this->partial('transcripts/_table', ['items' => $t['items'], 'showLetter' => $t['gpa'] !== null, 'tableClass' => 'doc']) ?>

<p><strong><?= e(__('transcripts.total_hours')) ?>: <?= e($t['snapshot']['totals']['hours'] ?? 0) ?></strong>
    <?php if ($t['gpa'] !== null): ?> · <strong>GPA: <?= e(number_format((float) $t['gpa'], 2)) ?></strong><?php if (!empty($h['gpa_basis'])): ?> <span class="muted-sm">(<?= e($h['gpa_basis']) ?>)</span><?php endif; ?><?php endif; ?></p>
<p class="muted-sm"><?= e(__('transcripts.hours_note')) ?></p>

<?php if (!empty($h['history'])): ?>
    <h2><?= e(__('transcripts.history')) ?></h2>
    <table>
        <tbody>
        <?php foreach ($h['history'] as $row): ?>
            <tr><td><?= e(format_date($row['from'])) ?> — <?= e($row['to'] !== null ? format_date($row['to']) : __('students.now')) ?></td><td><?= e($row['group']) ?></td><td><?= e(__('students.reasons.' . $row['reason'])) ?><?= $row['end_reason'] ? ' → ' . e(__('students.end_reasons.' . $row['end_reason'])) : '' ?></td><td><?= e($row['order'] ?? '') ?></td></tr>
        <?php endforeach; ?>
        </tbody>
    </table>
<?php endif; ?>

<p style="margin-top: 12mm"><?= e(__('transcripts.signature')) ?> ____________________ &nbsp;&nbsp; <?= e(__('transcripts.stamp')) ?></p>
<footer class="doc-footer">
    <?= e(__('transcripts.fingerprint')) ?>: <?= e(strtoupper(substr((string) $t['fingerprint'], 0, 16))) ?> · <?= e(__('transcripts.verify_at')) ?> <?= e($verifyUrl) ?>
</footer>

<?php if ($canRevoke): ?>
    <form method="post" action="<?= e(url('/transcripts/' . $t['id'] . '/revoke')) ?>" class="print-toolbar" style="position: static; margin-top: 8mm; border-radius: 6px">
        <?= csrf_field() ?>
        <label for="revokeReason"><?= e(__('transcripts.revoke')) ?>:</label>
        <input id="revokeReason" name="reason" maxlength="255" required placeholder="<?= e(__('schedule.reason')) ?>" style="padding: 6px; border-radius: 4px; border: 0; min-width: 240px">
        <button type="submit"><?= e(__('transcripts.revoke')) ?></button>
    </form>
<?php endif; ?>
